  "steps": [
    {
      "id": 1,
      "claim": "For a concave mirror the mirror equation is 1/f = 1/do + 1/di, with f > 0.",
      "evidence": "Standard thin‑mirror formula derived from spherical‑mirror geometry.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The linear magnification of a mirror is m = -di / do.",
      "evidence": "Definition of magnification for spherical mirrors (image height / object height).",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "When the object is far away (do → ∞), the image distance di = f.",
      "evidence": "Set 1/do → 0 in the mirror equation: 1/di = 1/f ⇒ di = f.",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "As do decreases from a large value toward f (do > f), di = f·do/(do – f) grows without bound, i.e., di → ∞.",
      "evidence": "Algebraic rearrangement of the mirror equation: di = f·do/(do – f); denominator → 0⁺ as do → f⁺, so di → +∞.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "The magnitude of magnification |m| = di / do = f/(do – f) also grows without bound as do → f⁺, so the image becomes taller.",
      "evidence": "Substitute di from step 4 into m = -di/do; the denominator (do – f) → 0⁺, making |m| → ∞.",
      "weight": 0.20,
      "depends_on": [2, 4]
    },
    {
      "id": 6,
      "claim": "Therefore, as the object moves from far away to near the focal point, the image moves away from the mirror and gets taller.",
      "evidence": "Step 4 shows image distance increases (moves away); step 5 shows magnification magnitude increases (image gets taller).",
      "weight": 0.20,
      "depends_on": [4, 5]
    }
  ],
  "answer": "B",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Image distance increases (moves away) but magnification also increases, so the image gets taller, not shorter."
    },
    {
      "answer": "C",
      "reason_rejected": "Image distance does not decrease; it increases as the object approaches the focal point."
    },
    {
      "answer": "D",
      "reason_rejected": "Although the image gets taller, it moves away from the mirror, not toward it."
    }
  ]
